import csv, json, math
from pathlib import Path
rows = list(csv.reader(Path("discoveries/schur-extensions/grid/ms3_witness_16383.txt").open(), delimiter=" ", skipinitialspace=True))
if any(len(row) != 2 for row in rows): raise ValueError("Expected integer/color pairs")
pairs = [(int(n), int(c)) for n, c in rows]
colors = dict(pairs)
if len(colors) != len(pairs) or set(colors) != set(range(2, 16384)): raise ValueError("Incomplete or duplicate domain")
if not set(colors.values()) <= {0, 1, 2}: raise ValueError("Invalid palette")
def violations(c):
    return [(a, b, a*b) for a in range(2, math.isqrt(16383)+1) for b in range(a, 16383//a+1) if c[a] == c[b] == c[a*b]]
first = violations(colors)
second = [(a, p//a, p) for p in range(4, 16384) for a in range(2, math.isqrt(p)+1) if p % a == 0 and colors[a] == colors[p//a] == colors[p]]
if first or second: raise ValueError("Monochromatic product triple")
corrupted = dict(colors)
corrupted[4] = corrupted[2]
if (2, 2, 4) not in violations(corrupted): raise ValueError("Rejecting control failed")
checked = sum(16383//a-a+1 for a in range(2, math.isqrt(16383)+1))
print(json.dumps({"n":16383,"colors":3,"integers":len(colors),"unordered_product_triples":checked,"monochromatic_triples":0,"independent_factorization_cross_check":True,"rejecting_control":"Recoloring 4 to match 2 detects (2,2,4)"}))
